import java.util.*;
import net.sf.l2j.gameserver.GameServer;
import net.sf.l2j.gameserver.model.actor.player.Experience;
import dev.l2j.autobots.Autobot;
import dev.l2j.autobots.autofarm.AutofarmManager;

/** Controlled death-event clock/history; real database and a second JVM verify survival decisions, not rewards. */
public class PersistentFitnessVerify extends OfflineTownVerify {
 static Object brain(Autobot b,long[] clock)throws Exception{return Class.forName("dev.l2j.autobots.population.economy.Fitness").getConstructor(Autobot.class,kotlin.jvm.functions.Function0.class).newInstance(b,(kotlin.jvm.functions.Function0<Long>)()->clock[0]);}
 static String mode(Object f)throws Exception{return invoke(f,"getMode").toString();}
 static void clear(int id)throws Exception{try(java.sql.Connection c=net.sf.l2j.L2DatabaseFactory.getInstance().getConnection();java.sql.ResultSet r=c.getMetaData().getTables(null,null,"autobot_fitness",null)){if(r.next())try(java.sql.PreparedStatement p=c.prepareStatement("DELETE FROM autobot_fitness WHERE obj_Id=?")){p.setInt(1,id);p.executeUpdate();}}}
 @SuppressWarnings("unchecked") public static void main(String[] args){try{
  if(!"yes".equals(System.getenv("L2_MOVEMENT_ISOLATED")))throw new IllegalStateException();GameServer.main(new String[0]);Object fm=singleton("offlinelife.OfflineFarmManager");invoke(member(fm,"travelTask").get(fm),"cancel");invoke(member(AutofarmManager.INSTANCE,"onUpdateTask").get(AutofarmManager.INSTANCE),"cancel");Autobot b=(Autobot)invoke(singleton("dao.AutobotsDao"),"loadByName","Weapons");check(b!=null,"stable population actor restores in this JVM");b.getStat().setLevel((byte)13);b.getStat().setExp(Experience.LEVEL[13]+1000);long xp=b.getExp();int cash=b.getAdena();long[] clock={System.currentTimeMillis()};boolean resume=Arrays.asList(args).contains("--resume");
  if(!resume){clear(b.getObjectId());Object first=brain(b,clock);invoke(first,"onDeath");invoke(first,"onDeath");Object next=brain(b,clock);check(mode(next).equals("Normal"),"two recent deaths preserve the existing three-death threshold");invoke(next,"onDeath");check(mode(next).equals("Farm"),"a replacement brain retains two deaths and lowers difficulty on the next one");if(Arrays.asList(args).contains("--plan-only")){System.out.println("PERSISTENT FITNESS PLAN ALL PASSED");System.exit(0);}invoke(next,"onDeath");invoke(next,"onDeath");check(mode(next).equals("Farm"),"partial repeated-failure history is saved without premature escalation");check(b.getExp()==xp&&b.getAdena()==cash,"memory fixture neither kills the actor nor changes rewards/resources");System.out.println("PERSISTENT FITNESS SAVE ALL PASSED");System.exit(0);}
  Object restored=brain(b,clock);check(mode(restored).equals("Farm"),"a genuinely new JVM restores the earlier Farm decision");invoke(restored,"onDeath");check(mode(restored).equals("NeedsGroup")&&Boolean.TRUE.equals(invoke(b,"getNeedsGroup")),"partial death history across JVMs escalates on the next failure");Object life=Class.forName("dev.l2j.autobots.population.LifeBehavior").getConstructor(Autobot.class).newInstance(b);invoke(b,"setLife",life);Object liveFitness=member(life,"fitness").get(life);kotlin.ranges.IntRange range=(kotlin.ranges.IntRange)invoke(singleton("population.HuntingSpots"),"targetLevels",b);check(mode(liveFitness).equals("NeedsGroup")&&range.getLast()==7,"a restored ordinary life uses the safer actual target window");
  clock[0]+=3600001;Object expired=brain(b,clock);check(Boolean.TRUE.equals(invoke(expired,"update"))&&mode(expired).equals("Normal"),"an hour without deaths and adequate gear still recovers normally using an injected clock");check(mode(brain(b,clock)).equals("Normal"),"the successful recovery is persisted too");
  clear(b.getObjectId());Object old=brain(b,clock);invoke(old,"onDeath");invoke(old,"onDeath");clock[0]+=3600001;Object fresh=brain(b,clock);invoke(fresh,"onDeath");check(mode(fresh).equals("Normal"),"expired partial death history does not trigger a false fallback");check(b.getExp()==xp&&b.getAdena()==cash,"restoring/recovering survival memory changes no experience or currency");invoke(singleton("dao.AutobotsDao"),"deleteBot",b.getObjectId());check(invoke(singleton("population.economy.FitnessStore"),"load",b.getObjectId())==null,"deleting the character removes its survival memory before its id can be reused");System.out.println("PERSISTENT FITNESS RESUME ALL PASSED");System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
